      "Line1": "வறியார்க்கொன்று ஈவதே ஈகைமற் றெல்லாம்",
      "Line2": "குறியெதிர்ப்பை நீர துடைத்து.",
      "Translation": "To give the poor is charity The rest is loan and vanity",
