      "Line1": "எப்பொருள் எத்தன்மைத் தாயினும் அப்பொருள்",
      "Line2": "மெய்ப்பொருள் காண்பது அறிவு.",
      "Translation": "Knowledge is truth of things to find In every case of every kind",
      "mv": "எப்பொருள் எத்தன்மையதாய்த் தோன்றினாலும் (அத்தோற்றத்தை மட்டும் கண்டுமங்காமல்) அப் பொருளின் உண்மையான இயல்பை அறிவதே மெய்யுணர்வு.",
