      "Line1": "மனத்தானாம் மாந்தர்க் குணர்ச்சி இனத்தானாம்",
      "Line2": "இன்னான் எனப்படுஞ் சொல்.",
      "Translation": "Wisdom depends upon the mind The worth of man upon his friend",
